def execute(p,source,needs,literals):
    """Execute every original statement/branch/assertion within real owned-resource scopes; never treat missing external JWT/OIDC prerequisites as source success."""
    with Runtime(p,needs,literals):getattr(sources,source)()
    return {'request_transport':'official_sdk','credential_chain':'configured alt STS -> actual AssumeRoleWithWebIdentity Credentials -> independent S3 SDK worker','source_policy_strings_preserved':True}


OPS='identity_iam identity_alt api.sts.AssumeRoleWithWebIdentity '+ ' '.join('api.iam.'+x for x in ('GetRole','CreateRole','DeleteRole','PutRolePolicy','DeleteRolePolicy','CreateOpenIDConnectProvider','GetOpenIDConnectProvider','ListOpenIDConnectProviders','DeleteOpenIDConnectProvider'))+' bucket_head bucket_create_raw bucket_delete delete put_http get_http head_http copy wire_headers api.PutBucketPolicy api.PutBucketTagging'
CASES=tuple(case('ceph_sts_web_'+name.removeprefix('test_'),'Ceph STS WebIdentity/session原始向量','固定issuer、原trust/role/session/bucket政策、原JWT环境变量与全部原分支断言；真实返回凭据进入官方S3消费者；实际新建资源finally清理',OPS,lambda p,n=name,r=needs,l=literals:execute(p,n,r,l),name,SOURCE) for name,line,needs,literals in SPECS)


def register(registry):registry.add_suite(Suite('ceph_sts_web',frozenset(OPS.split()),lambda ctx:run_cases(ctx,CASES),tuple(c.metadata() for c in CASES),case_capabilities=True))
